contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test sequence: deposit amount via addToBalance, then try withdrawBalance.
    // Parameters: amount to deposit (must be <= this contract balance) and a flag whether to attempt withdraw after.
    function run(uint256 amount, bool doWithdraw) public payable {
        require(address(this).balance >= amount);

        // Read balances before
        uint256 beforeUserBalance = c.getBalance(address(this));
        uint256 beforeCbalance = address(c).balance;

        // Perform deposit: this will call c.addToBalance() sending `amount` wei
        bool depositReverted;
        if (amount == 0) {
            // calling with 0 is allowed; still treat uniformly
            try c.addToBalance{value: 0}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        } else {
            try c.addToBalance{value: amount}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        }

        // Observables after deposit attempt
        uint256 midUserBalance = c.getBalance(address(this));
        uint256 midCbalance = address(c).balance;

        bool withdrawReverted = false;
        uint256 afterUserBalance = midUserBalance;
        uint256 afterCbalance = midCbalance;

        if (doWithdraw) {
            // attempt withdraw; record revert status
            try c.withdrawBalance() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
            afterUserBalance = c.getBalance(address(this));
            afterCbalance = address(c).balance;
        }

        /* General rule asserted:
           - If deposit did not revert, then midUserBalance == beforeUserBalance + amount
             and midCbalance == beforeCbalance + amount.
           - If deposit reverted, balances remain unchanged.
           - If withdraw was attempted and did not revert then afterUserBalance == 0
             and afterCbalance == midCbalance - midUserBalance (i.e., C's balance decreased by the withdrawn amount).
           - If withdraw reverted then balances remain as before the withdraw attempt.
        */
        assert(
            (
                (!depositReverted) ? (
                    midUserBalance == beforeUserBalance + amount && midCbalance == beforeCbalance + amount
                ) : (
                    midUserBalance == beforeUserBalance && midCbalance == beforeCbalance
                )
            )
            && (
                doWithdraw ? (
                    (!withdrawReverted) ? (
                        afterUserBalance == 0 && midCbalance >= midUserBalance && afterCbalance == midCbalance - midUserBalance
                    ) : (
                        afterUserBalance == midUserBalance && afterCbalance == midCbalance
                    )
                ) : true
            )
        );
    }

    receive() external payable { }
}

