contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit into c from this contract
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance in test");

        // read balance of this test contract as seen in c (msg.sender will be this contract for calls)
        uint beforeUser = c.getBalance(address(this));
        uint beforeContractBalance = address(c).balance;

        // perform the state-changing call: addToBalance with Ether amount
        bool reverted;
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterUser = c.getBalance(address(this));
        uint afterContractBalance = address(c).balance;

        // If the call did not revert, then the user's recorded balance increased by exactly amount
        // and the contract's Ether balance increased by exactly amount.
        // If the call reverted, neither observed balance should have changed.
        assert(
            reverted
            ? (afterUser == beforeUser && afterContractBalance == beforeContractBalance)
            : (afterUser == beforeUser + amount && afterContractBalance == beforeContractBalance + amount)
        );
    }

    // allow receiving Ether so this contract can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run: params are amount to deposit and a second arbitrary uint (unused) to allow variety
    function run(uint256 amount, uint256 /*unused*/) public payable {
        require(address(this).balance >= amount, "not enough balance to send");

        // initial observations
        uint beforeRecorded = c.getBalance(address(this));
        uint beforeCbalance = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform addToBalance sending `amount` wei to c
        c.addToBalance{value: amount}();

        // ensure recorded increased by exactly amount (since add_uint256 prevents overflow)
        uint midRecorded = c.getBalance(address(this));

        // attempt withdraw and capture whether it reverted
        bool withdrewReverted;
        try c.withdrawBalance() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint afterRecorded = c.getBalance(address(this));
        uint afterCbalance = address(c).balance;
        uint afterThis = address(this).balance;

        // If withdraw did not revert then: recorded balance for this caller must be zero,
        // and the increase in this contract's balance is at most the amount we deposited
        // (since withdraw sends at most that recorded amount back). Also contract's balance
        // decreased by at least the amount returned to this contract.
        assert(
            withdrewReverted || (
                afterRecorded == 0
                && afterThis - beforeThis <= amount
                && beforeCbalance - afterCbalance >= (beforeThis <= afterThis ? afterThis - beforeThis : 0)
            )
        );
    }

    // allow receiving Ether during tests (fallback from c.withdrawBalance)
    receive() external payable {}
}

