        // perform the deposit sending exactly `amount`
        c.addToBalance{value: amount}();

        // observe after-values
        uint256 afterRecorded = c.getBalance(address(this));
        uint256 afterCbal = address(c).balance;

        // General rule: recorded balance increased by exactly amount and contract balance increased by exactly amount
        assert(afterRecorded == beforeRecorded + amount && afterCbal == beforeCbal + amount);
